def ready_for_cutover(src, dst, cfg) -> tuple[bool, str]:
    lag = dst.replay_lag_seconds()
    if lag > cfg.max_lag_seconds:  # e.g. 2.0
        return False, f"lag too high: {lag:.1f}s"
    if src.schema_version() != dst.schema_version():
        return False, "schema version mismatch"
    if dst.replication_errors() > 0:
        return False, "replication worker has errors"
    if shadow_mismatch_rate() > cfg.max_mismatch:
        return False, "shadow read mismatch too high"
    if src.open_write_txns() > cfg.max_open_txns:
        return False, "too many open write txns to drain"
    return True, "ok"

def cutover(src, dst, cfg):
    ok, reason = ready_for_cutover(src, dst, cfg)
    if not ok:
        raise GateClosed(reason)
    epoch = src.fence_writes()  # reject writes with old token
    src.wait_for_drain(timeout_s=cfg.drain_timeout)
    dst.wait_for_replay(lag_seconds=0, timeout_s=cfg.replay_timeout)
    dst.promote(expected_epoch=epoch + 1)
